import heapq
W = {("A", "B"): 4, ("A", "C"): 1, ("C", "B"): 2, ("B", "D"): 5, ("C", "D"): 8, ("D", "E"): 3}
adj = {}
for (a, b), w in W.items(): adj.setdefault(a, []).append((b, w)); adj.setdefault(b, []).append((a, w))
def dist(src):
    d, order, pq = {}, [], [(0, src)]
    while pq:
        x, v = heapq.heappop(pq)
        if v in d: continue
        d[v] = x; order.append(x)
        for u, w in adj[v]:
            if u not in d: heapq.heappush(pq, (x + w, u))
    return d, order
result = dist("A")[0]["B"]

